package gen

import (
	"fmt"
	"strconv"
	"strings"
)

const generatedHeader = `// DO NOT EDIT.
// Generated by protoc-gen-wtcrdt (tools/protoc-gen-wtcrdt) from the wt.crdt and buf.validate
// options in proto/; regenerate with ` + "`make -C tools/protoc-gen-wtcrdt generate`" + `.
`

// swiftPolicyCase maps a policy to its Swift enum case name.
var swiftPolicyCase = map[Policy]string{
	PolicyAtomic:   "atomic",
	PolicyStruct:   "structure",
	PolicySequence: "sequence",
	PolicyText:     "text",
	PolicySet:      "set",
	PolicyVariant:  "variant",
}

var swiftFallbackCase = map[Fallback]string{
	FallbackUnset:       "unset",
	FallbackCached:      "cached",
	FallbackPlaceholder: "placeholder",
}

func swiftString(s string) string {
	return strconv.Quote(s) // Swift string literal escapes are a superset of Go's for ASCII
}

func swiftOptionalString(s string) string {
	if s == "" {
		return "nil"
	}
	return swiftString(s)
}

// swiftIdentifier makes a Swift identifier out of a fully qualified proto name.
func swiftIdentifier(fqn string) string {
	return strings.ReplaceAll(fqn, ".", "_")
}

// EmitSwiftMergeTable renders MergeTable.swift: `WTMergeTable`, its nested policy types and the
// per-message tables, plus the JSON document and its version.
func EmitSwiftMergeTable(t *Table) []byte {
	var b strings.Builder
	b.WriteString(generatedHeader)
	b.WriteString(`// swiftlint:disable all

/// The merge table (docs/spec/crdt-model.adoc, "Merge policies"): for every message reachable
/// from ` + "`NodeProps`" + `, ` + "`CommonProps`" + ` and ` + "`Node`" + `, the effective merge policy of each field.  The engine
/// walks a FieldPath with it and contains no per-feature code.  ` + "`json`" + ` is the same table as the
/// server sends in ` + "`Welcome.merge_table`" + `; ` + "`version`" + ` compares the two without parsing.
public enum WTMergeTable {
    /// How concurrent writes to a field are reconciled (wt.crdt.Merge without its prefix).
    public enum Policy: String, Sendable, Hashable, Codable, CaseIterable {
        /// The whole value is one register; the op with the greatest OpId wins.
        case atomic = "ATOMIC"
        /// Each field of the message is its own register (recursively).
        case structure = "STRUCT"
        /// A repeated message whose first field is ` + "`ElementId id = 1`" + `; elements are inserted,
        /// moved and deleted individually with a fractional position each.
        case sequence = "SEQUENCE"
        /// A RichText field: Fugue characters plus Peritext marks.
        case text = "TEXT"
        /// An add-wins observed-remove set of scalars or ids.
        case set = "SET"
        /// An enum ` + "`kind`" + ` register plus one STRUCT message per case.
        case variant = "VARIANT"
    }

    /// What a NodeRef reads as while its target is deleted or unknown (wt.crdt.RefFallback).
    public enum RefFallback: String, Sendable, Hashable, Codable, CaseIterable {
        case unset = "UNSET"
        case cached = "CACHED"
        case placeholder = "PLACEHOLDER"
    }

    /// One row: the effective policy of one field.
    public struct FieldPolicy: Sendable, Hashable {
        public let fieldNumber: Int
        public let name: String
        public let policy: Policy
        public let onDangling: RefFallback
        /// Never leaves the device: view state stored in the document for convenience.
        public let localOnly: Bool
        /// The protobuf kind: "double", "string", "bytes", "enum", "message", "map", ...
        public let type: String
        public let repeated: Bool
        /// The fully qualified message or enum name for those kinds.
        public let typeName: String?
        /// The element message of a SEQUENCE field.
        public let elementMessage: String?
        /// The oneof the field belongs to, if any.
        public let oneof: String?

        public init(
            fieldNumber: Int, name: String, policy: Policy, onDangling: RefFallback,
            localOnly: Bool, type: String, repeated: Bool, typeName: String?,
            elementMessage: String?, oneof: String?
        ) {
            self.fieldNumber = fieldNumber
            self.name = name
            self.policy = policy
            self.onDangling = onDangling
            self.localOnly = localOnly
            self.type = type
            self.repeated = repeated
            self.typeName = typeName
            self.elementMessage = elementMessage
            self.oneof = oneof
        }
    }

    /// The rows of one message, keyed by field number.
    public struct MessagePolicy: Sendable, Hashable {
        public let name: String
        public let fields: [Int: FieldPolicy]

        public init(name: String, fields: [Int: FieldPolicy]) {
            self.name = name
            self.fields = fields
        }

        public subscript(fieldNumber: Int) -> FieldPolicy? { fields[fieldNumber] }
    }

    /// A MERGE_VARIANT message: its ` + "`kind`" + ` discriminator and the message fields holding each case.
    public struct VariantPolicy: Sendable, Hashable {
        public let kindField: Int
        public let caseFields: [Int]

        public init(kindField: Int, caseFields: [Int]) {
            self.kindField = kindField
            self.caseFields = caseFields
        }
    }

    /// SHA-256 (hex) of the canonical JSON table without its ` + "`version`" + ` key.
    public static let version = ` + swiftString(t.Version()) + `

    /// The rows of every message, by fully qualified proto name.
    public static let messages: [String: MessagePolicy] = [
`)
	for _, name := range t.MessageNames() {
		fmt.Fprintf(&b, "        %s: %s,\n", swiftString(name), swiftIdentifier(name))
	}
	b.WriteString(`    ]

    /// The MERGE_VARIANT messages, by fully qualified proto name.
    public static let variants: [String: VariantPolicy] = [
`)
	if len(t.Variants) == 0 {
		b.WriteString("        :\n") // Swift accepts `[` `:` `]` across lines as the empty dictionary
	}
	for _, name := range t.VariantNames() {
		v := t.Variants[name]
		cases := make([]string, len(v.CaseFields))
		for i, c := range v.CaseFields {
			cases[i] = strconv.Itoa(int(c))
		}
		fmt.Fprintf(&b, "        %s: VariantPolicy(kindField: %d, caseFields: [%s]),\n", swiftString(name), v.KindField, strings.Join(cases, ", "))
	}
	b.WriteString(`    ]

    /// The row for one field, or nil when the message or field is not in the table (an op
    /// naming it is a deterministic no-op, crdt-model.adoc "Totality").
    public static func field(_ message: String, _ fieldNumber: Int) -> FieldPolicy? {
        messages[message]?.fields[fieldNumber]
    }

    /// The serialized table as the server sends it in ` + "`Welcome.merge_table`" + ` (UTF-8 JSON).
    public static let json: String = #"""
`)
	b.Write(t.SerializedJSON())
	b.WriteString(`"""#
`)
	for _, name := range t.MessageNames() {
		m := t.Messages[name]
		fmt.Fprintf(&b, "\n    private static let %s = MessagePolicy(\n        name: %s,\n        fields: [\n", swiftIdentifier(name), swiftString(name))
		for _, f := range m.Fields {
			fmt.Fprintf(&b, "            %d: FieldPolicy(\n", f.Number)
			fmt.Fprintf(&b, "                fieldNumber: %d, name: %s, policy: .%s, onDangling: .%s,\n", f.Number, swiftString(f.Name), swiftPolicyCase[f.Policy], swiftFallbackCase[f.OnDangling])
			fmt.Fprintf(&b, "                localOnly: %t, type: %s, repeated: %t, typeName: %s,\n", f.LocalOnly, swiftString(f.Type), f.Repeated, swiftOptionalString(f.TypeName))
			fmt.Fprintf(&b, "                elementMessage: %s, oneof: %s\n", swiftOptionalString(f.ElementMessage), swiftOptionalString(f.Oneof))
			b.WriteString("            ),\n")
		}
		if len(m.Fields) == 0 {
			b.WriteString("            :\n")
		}
		b.WriteString("        ]\n    )\n")
	}
	b.WriteString("}\n")
	return []byte(b.String())
}
